ALTER TABLE "orders" ALTER COLUMN "current_approval_snapshot_id" DROP NOT NULL;--> statement-breakpoint

ALTER TABLE "orders" ADD CONSTRAINT "ck_orders__custom_chain_by_origin" CHECK (("orders"."origin" = 'CUSTOM' and "orders"."custom_request_id" is not null and "orders"."accepted_quotation_version_id" is not null and "orders"."current_approval_snapshot_id" is not null) or ("orders"."origin" = 'READY_MADE' and "orders"."custom_request_id" is null and "orders"."accepted_quotation_version_id" is null and "orders"."current_approval_snapshot_id" is null));--> statement-breakpoint

