ALTER TABLE "order_transitions" DROP CONSTRAINT "ck_order_transitions__from_status_allowed";--> statement-breakpoint
ALTER TABLE "order_transitions" DROP CONSTRAINT "ck_order_transitions__to_status_allowed";--> statement-breakpoint
