ALTER TABLE "order_transitions" ADD CONSTRAINT "ck_order_transitions__to_status_allowed" CHECK ("order_transitions"."to_status" in ('AWAITING_DEPOSIT', 'DEPOSIT_PAID', 'IN_PRODUCTION', 'PRODUCTION_COMPLETED', 'AWAITING_FINAL_PAYMENT', 'READY_FOR_DELIVERY', 'DELIVERED', 'COMPLETED', 'ON_HOLD', 'CANCELLING', 'CANCELLED', 'AWAITING_SHIPPING_FEE', 'AWAITING_PAYMENT'));--> statement-breakpoint

