CREATE INDEX "ix_secure_access_grants__order_id" ON "secure_access_grants" USING btree ("order_id");--> statement-breakpoint

--> STEP 7 — the origin guard trigger family.
--
-- One function, three rules, selected by TG_ARGV[0]:
--   'origin_immutable'  — orders.origin never changes after insert
--   'item_subject'      — order_items approval/subject by parent origin
--   'obligation_kind'   — payment_obligations kind by parent origin
--
-- Fields are read through `to_jsonb(NEW)` rather than `NEW.<column>` so one
-- function can serve triggers on three differently-shaped tables — the access
-- shape 0030's freeze guard and 0034's placement guard already use.
CREATE OR REPLACE FUNCTION public.fn_app12_order_origin_guard()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_rule text := TG_ARGV[0];
  v_new jsonb := to_jsonb(NEW);
  v_old_origin text;
  v_order_id uuid;
  v_origin text;
BEGIN
  IF v_rule = 'origin_immutable' THEN
    v_old_origin := to_jsonb(OLD) ->> 'origin';
    IF v_old_origin IS DISTINCT FROM (v_new ->> 'origin') THEN
      RAISE EXCEPTION
        'order origin violation: orders.origin is immutable (% -> %)',
        v_old_origin, v_new ->> 'origin'
        USING ERRCODE = '23000';
    END IF;
    RETURN NEW;
  END IF;

  v_order_id := (v_new ->> 'order_id')::uuid;
  SELECT o.origin INTO v_origin FROM public.orders o WHERE o.id = v_order_id;

  IF v_origin IS NULL THEN
    -- Unreachable while the child's own foreign key to `orders` stands; raised
    -- rather than ignored so a future schema change cannot silently turn this
    -- guard into a pass.
    RAISE EXCEPTION
      'order origin violation: % row % names order %, which does not exist',
      TG_TABLE_NAME, v_new ->> 'id', v_order_id
      USING ERRCODE = '23503';
  END IF;

  IF v_rule = 'item_subject' THEN
    IF v_origin = 'CUSTOM' AND (v_new ->> 'approval_snapshot_id') IS NULL THEN
      RAISE EXCEPTION
        'order origin violation: order item % on CUSTOM order % requires approval_snapshot_id (D7-07)',
        v_new ->> 'id', v_order_id
        USING ERRCODE = '23000';
    END IF;

    IF v_origin = 'READY_MADE' THEN
      IF (v_new ->> 'approval_snapshot_id') IS NOT NULL THEN
        RAISE EXCEPTION
          'order origin violation: order item % on READY_MADE order % may not carry an approval snapshot',
          v_new ->> 'id', v_order_id
          USING ERRCODE = '23000';
      END IF;

      IF (v_new ->> 'sku_id') IS NULL THEN
        RAISE EXCEPTION
          'order origin violation: order item % on READY_MADE order % must name a SKU, never a customer-owned product',
          v_new ->> 'id', v_order_id
          USING ERRCODE = '23000';
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  IF v_rule = 'obligation_kind' THEN
    IF v_origin = 'CUSTOM' AND (v_new ->> 'kind') NOT IN ('DEPOSIT', 'REMAINING') THEN
      RAISE EXCEPTION
        'order origin violation: payment obligation % on CUSTOM order % must be DEPOSIT or REMAINING, not %',
        v_new ->> 'id', v_order_id, v_new ->> 'kind'
        USING ERRCODE = '23000';
    END IF;

    IF v_origin = 'READY_MADE' AND (v_new ->> 'kind') <> 'FULL' THEN
      RAISE EXCEPTION
        'order origin violation: payment obligation % on READY_MADE order % must be FULL, not %',
        v_new ->> 'id', v_order_id, v_new ->> 'kind'
        USING ERRCODE = '23000';
    END IF;

    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'order origin violation: unknown guard rule %', v_rule
    USING ERRCODE = '23000';
END
$$;--> statement-breakpoint

CREATE TRIGGER tg_orders__origin_immutable
BEFORE UPDATE ON "orders"
FOR EACH ROW EXECUTE FUNCTION public.fn_app12_order_origin_guard('origin_immutable');--> statement-breakpoint

CREATE TRIGGER tg_order_items__origin_subject
BEFORE INSERT OR UPDATE ON "order_items"
FOR EACH ROW EXECUTE FUNCTION public.fn_app12_order_origin_guard('item_subject');--> statement-breakpoint

CREATE TRIGGER tg_payment_obligations__origin_kind
BEFORE INSERT OR UPDATE ON "payment_obligations"
FOR EACH ROW EXECUTE FUNCTION public.fn_app12_order_origin_guard('obligation_kind');
